  const row = async (r, qs, col, ms = 1500) => { const per = ms / qs.length; for (const q of qs) { cube('', col, [0.22, 0.3, 0.6], X(q), 0.15, Z(r), 2); await beat(tok, per); } };
  const name = (r, t) => tag(t, 'ptr', -6.3, 0.2, Z(r));
