  await step(tok);                                   // 197.3 i = 0: 0 < 0 no → 0 times
  await rowI(0, 0); tot.mood('calm');
  say('i = 0：0 < 0 不成立，stmt 一次也沒做', '0 次');
  await step(tok);                                   // 219.9 i = 1: j = 0 → once
  await rowI(1, 300);
  say('i = 1：j = 0 成立，j = 1 不成立', '1 次');
  await step(tok);                                   // 242 i = 2: j = 0, 1
