  col(4); await ex(4, 'n³'); tag('例：矩陣相乘', 'idx', X(4), 1.1, 0.9);
  say('n³ 叫 cubic', '矩陣相乘');
  await step(tok);                                   // 131.8 2ⁿ: exponential
