  await step(tok);                                   // 442.8 f belongs to n's class
  glow(ms[3], GOLD); f.mood('happy');
  say('f(n) 本身屬於 n 這一類', '');
  await step(tok);                                   // 456.8 n and everything larger: upper bounds
  for (let k = 3; k < AB_CL.length; k++) { tint(ms[k], AB.green); await beat(tok, 150); }
