    const dt = tag('data：男生編號', 'idx', XS[0], Y + 1.1, 0), lk = tag('link → 下一筆', 'idx', XS[0] + 0.9, Y - 0.9, 0);
    say('每筆資料：data 欄位 + link 欄位', 'link 是 pointer，指向下一筆'); await beat(tok, 2800);
    kill(dt); kill(lk);
