  await step(tok);                                    // 4641.0 think at a high level: prove + analyse first
  cl.kill(); cd.hl(-1); remove(nt);
  const a = jCard('證明正確', J.blue, -3.6, -0.4, 2.4, 2.4, 2, 0.55), b = jCard('分析夠快', J.blue, 0, -0.4, 2.4, 2.4, 2, 0.55);
