  const st = [pkt('free 單身', -3.8, 5.7), pkt('engaged 訂婚', 0, 5.7), pkt('married 結婚', 3.8, 5.7)];
  arrow(V3(-2.7, 5.7, 0), V3(-1.4, 5.7, 0)); arrow(V3(1.4, 5.7, 0), V3(2.7, 5.7, 0));
  say('每個人會經過三個階段', 'free → engaged → married');
