  const m1 = j2who('m1', 'm', -3.4, 2.6), m2 = j2who('m2', 'm', -3.4, 0.2), w1 = j2who('w1', 'w', 3.4, 2.6), w2 = j2who('w2', 'w', 3.4, 0.2);
  [m1, m2, w1, w2].forEach((p) => p.set('free'));
