  for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) cells.push(cube('', GRAY, [1.1, 0.1, 1.0], X(j), 0.05, Z(i)));
  say('Formulation 很乾淨：n 個男生、n 個女生', '每個人都有一份對所有異性的 preference list');
  await step(tok); // 379.8 last time / today
