  me.look(1); glow(bs[5], '#333333'); await beat(tok, 700); me.look(0);
  say('依序看左邊、看右邊', '');
  await step(tok);                                   // 1713.4 if a[n/2] < a[n/2−1]: left half
  cd.hl(0); glow(bs[5], null);
