    for (let k = 0; k < 4; k++) { await mWalk(tok, me, g.X(c), g.Y(k) + 0.45, 0.4, 220); glow(g.cells[k][c], '#333333'); if (PK[k][c] > PK[best][c]) best = k; }
    for (let k = 0; k < 4; k++) glow(g.cells[k][c], null);
