  say('回到 lecture 的 peak finding：先做 1D，再做 2D', '');
  await step(tok);                                   // 1952.6 numbers 3, 4, 5, 6, 7, 6, 5, 4
  bs = A.map((v, i) => mBar(v, v * 0.6, M.blue, X(i)));
