  await step(tok);                                   // 2343.8 c + c + T(n/4)
  row('= 2c + T(n/4)', 2); sz('n/4', 2, 0.8);
  say('再展開一次：c + c + T(n/4)', '');
  await step(tok);                                   // 2367.8 i·c + T(n/2ⁱ)
  row('= i·c + T(n/2ⁱ)', 3); sz('n/2ⁱ', 3, 0.5);
