  me.set('!'); me.mood('happy');
  say('log n 主導常數：T(n) = Θ(log n)', '');
  await step(tok);                                   // 2558.8 key idea: force it to stop at the base case
  note('一直展開，強迫它停在 base case', 3.4, 7.3);
