  relabel(eq, 'T(n, m) = Θ(1) + Θ(m) + T(n/2, m) = Θ(m) + T(n/2, m)'); glow(eq, GOLD);
  say('T(n, m) = Θ(1) + Θ(m) + T(n/2, m)', '= Θ(m) + T(n/2, m)');
  await step(tok);                                   // 3077.5 base case: one column → max is a peak
  pkt('base case：只剩一欄 → 最大值就是 peak', 0, 5.4);
