  await step(tok);                                   // 3118.1 m never changes → like the 1D recurrence
  note('m 不變 → 當常數 → 就像 T(n) = c + T(n/2)', -2.0, 6.6);
  say('m 一直不變，當成常數：就跟 1D 的遞迴式一模一樣', '');
  await step(tok);                                   // 3155.0 Θ(m log n)
  relabel(eq, 'T(n, m) = Θ(m log n)'); glow(eq, GREEN);
