  cd = code(['1 def inner_product(L1, L2):', '2   sum = 0.0', '3   for word1, count1 in L1:', '4     for word2, count2 in L2:', '5       if word1 == word2:', '6         sum += count1 * count2', '7   return sum'], -3.8, 6.8, 0.5);
  say('來分析 inner_product：這個比較簡單', '');
