  f1 = mRow(['f', 'o', 'x'], 1.6, { cx: 2.6, gap: 0.6, s: 0.5, col: M.blue }); f2 = mRow(['t', 'h', 'e'], 0.8, { cx: 2.6, gap: 0.6, s: 0.5, col: M.blue });
