  say('"foy" 和 "fox"：前兩個一樣，第三個才不同', '');
  await step(tok);                                   // 2582.5 string == is O(w); English → constant
  tag('Θ(w)', 'ptr alt', 4.6, 1.2); cost(4, 'w', 'L1·L2');
