  await step(tok); // 3355 take the minimum of these
  clear(); glow(N[23], GREEN);
  say('自己的 min = min(自己, 左 min, 右 min)', 'min(23, 4, 42) = 4');
  await step(tok); // 3359 special cases: no left child → you're the min
