  say('insert、delete、insert、delete……', '每次操作都要線性時間！');
  await step(tok); // 1398 bouncing between 2^k and 2^(k+1)
  noT('在 2ᵏ 和 2ᵏ⁺¹ 之間來回抖動', 0, 4.0);
  say('在 2ᵏ 和 2ᵏ⁺¹ 之間來回跳', '太慢了');
  await step(tok); // 1428 shrink at n = m/3 or so
