  say('h(496, 2) = 1', '是 586 → 又失敗');
  await step(tok); // 896 h(496, 3) = 3
  glow(T[1], null); move(k, X(3), 2.2);
  say('第三次：h(496, 3) = 3');
  await step(tok); // 905 great, insert 496
