  say('回顧：從大數 n 出發，改用 mod p', '');
  await step(tok);                                   // 2389.3 mod p got rid of all big numbers
  cube('hash < p', M3.blue, [1.6, 0.5, 0.8], -2, 0.25, 1.5, 2); cube('magic < p', M3.blue, [1.6, 0.5, 0.8], 0.4, 0.25, 1.5, 2);
  say('mod p 把大數都消掉了', '裡面只剩小數字');
