// T(n) = T(√n) + 1：一條鏈的遞迴樹（第一段畫樹、第二段找樹高）
function m3SqrtLevel(h, label, last) {
  const y = 6.4 - h * 1.25;
  const n = cube(label, last ? M3.purple : M3.blue, [2.0, 0.6, 1], -3, y, 0, 1.5);
  const c = tag('成本 1', 'ptr alt', 0.2, y);
  return { n, c, y };
}
