// 假硬幣：天平（第一段策略與 log₃ N、第二段決策樹下界）
function m3Scale(nCoins, fake) {
  const coins = []; for (let i = 0; i < nCoins; i++) coins.push(cube(String(i + 1), i === fake ? '#efe0a6' : M3.gold, [0.7, 0.25, 0.7], -4 + i * 1, 0.13, 2.6));
  return coins;
}
